//! dbt schema types, generated by `build.rs` with typify.
//!
//! `build.rs` preprocesses the pristine schemas under `schemas/` (the rules,
//! and why each exists, are documented in `build/preprocess.rs`) and lets
//! typify generate each module below into `OUT_DIR`; `just generated` writes
//! them out formatted, to read.
//!
//! typify's output is not ours to lint: through `include!` clippy would read
//! it as this crate's code, which `import_types!` kept it from.
#![allow(clippy::all)]

// ---- YAML files (dbt-labs/dbt-jsonschema) ----

pub mod dbt_project {
    include!(concat!(env!("OUT_DIR"), "/dbt_project.rs"));
}

pub mod dbt_yml_files {
    include!(concat!(env!("OUT_DIR"), "/dbt_yml_files.rs"));
}

pub mod packages {
    include!(concat!(env!("OUT_DIR"), "/packages.rs"));
}

pub mod selectors {
    include!(concat!(env!("OUT_DIR"), "/selectors.rs"));
}

// ---- JSON artifacts (dbt-labs/schemas.getdbt.com): read through the
// ---- artifact leniency rules; `manifest` compiles the documented
// ---- projection only, never the 946 KB schema.

pub mod run_results {
    include!(concat!(env!("OUT_DIR"), "/run_results.rs"));
}

pub mod sources {
    include!(concat!(env!("OUT_DIR"), "/sources.rs"));
}

pub mod catalog {
    include!(concat!(env!("OUT_DIR"), "/catalog.rs"));
}

pub mod manifest {
    include!(concat!(env!("OUT_DIR"), "/manifest.rs"));
}
